229	function runScanCommand({ root = process.cwd(), ci = false, json = false, silent = false }: ScanOptions) {
230	  const result = Scanners.scanCodebase({ root });
231	
232	  if (json) {
233	    console.log(JSON.stringify(result, null, 2));
234	    return result;
235	  }
236	
237	  if (!silent) {
238	    log.info('Scan completed.', {
239	      totalFiles: result.totalFiles,
240	      aiFiles: result.aiFiles.length
241	    });
242	    if (result.aiFiles.length) {
243	      console.log('AI-related files:');
244	      result.aiFiles.forEach((file) => console.log(`  - ${path.relative(root, file)}`));
245	    }
246	    if (!result.aiFiles.length) {
247	      log.info('No AI indicators detected in scope.');
248	    }
249	    if (ci) {
250	      log.info('CI mode: exiting after scan.');
251	    }
252	  }
253	
254	  return result;
255	}
