257	type FetchLike = (input: unknown, init?: unknown) => Promise<unknown>;
258	
259	let cachedFetch: FetchLike | null = null;
260	
261	async function resolveFetchImplementation(): Promise<FetchLike> {
262	  if (typeof (globalThis as { fetch?: FetchLike }).fetch === 'function') {
263	    return (globalThis as { fetch: FetchLike }).fetch.bind(globalThis);
264	  }
265	  if (cachedFetch) return cachedFetch;
266	  const mod = await import('node-fetch');
267	  cachedFetch = (mod.default ?? mod) as FetchLike;
268	  return cachedFetch;
269	}
