export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  // Process thresholds if provided
  if (thresholds && typeof thresholds === 'object') {
    const thresholdEntries = Object.entries(thresholds);
    const thresholdsArray = [];
    let allPassed = true;

    thresholdEntries.forEach(([metricId, min]) => {
      // Find the matching metric
      const metric = evaluations.find((m) => m.id === metricId);
      const score = metric?.score ?? null;
      const passed = score !== null && score >= min;

      if (!passed) {
        allPassed = false;
      }

      thresholdsArray.push({
        metric: metricId,
        min,
        score,
        passed
      });
    });

    report.passed = allPassed;
    report.thresholds = thresholdsArray;
  }

  return report;
}

